void f32(SnapshotWriter& out,float value){if(!std::isfinite(value))throw std::runtime_error("Invalid destructable snapshot real");out.u32(std::bit_cast<std::uint32_t>(value));}
void f64(SnapshotWriter& out,double value){if(!std::isfinite(value))throw std::runtime_error("Invalid destructable snapshot time");out.u64(std::bit_cast<std::uint64_t>(value));}
