Bytes ScriptSession::encodeDestructables(const jass::StableHandleMap& encodeHandle) const {
    if(!runtime_.snapshotSafe() || failed_ || !world_ || !setupApplied_ || !contexts_.empty() || experimentalSelectionSync_ || !networkPlayers_.empty())throw std::runtime_error("Destructable snapshot requires a quiescent local session");std::map<std::uint32_t,std::uint32_t> placed;for(size_t i=0;i<placedDestructables_.size();++i)if(auto id=placedDestructables_[i];id && !placed.emplace(id,std::uint32_t(i+1)).second)throw std::runtime_error("Duplicate placed destructable handle");std::vector<std::uint32_t> handles;for(size_t i=0;i<objects_.size();++i)if(objects_[i].kind==NativeKind::Destructable)handles.push_back(handleBase+std::uint32_t(i));if(handles.size()>1048576 || (!handles.empty() && !encodeHandle))throw std::runtime_error("Destructable snapshot requires handle mapping");SnapshotWriter out(budget-64);out.u32(tag("SDES"));out.u32(1);out.text(world_->resources().mapDigest(),64);f64(out,simulationTime_);out.size(placedDestructables_.size());out.size(handles.size());std::set<std::uint32_t> stable;
    for(auto id:handles){auto& object=objects_[id-handleBase];auto mapped=encodeHandle("destructable",id);if(!mapped || !stable.insert(mapped).second)throw std::runtime_error("Invalid destructable handle mapping");out.u32(mapped);out.u32(placed.contains(id)?placed.at(id):0);out.u32(object.alive?1:0);if(!object.alive)continue;auto found=destructables_.find(id);if(found==destructables_.end() || !found->second || found->second->removed || found->second->handle!=id)throw std::runtime_error("Invalid live destructable state");auto& d=*found->second;auto visual=doodad(d.doodadIndex);if(!visual || visual->handle!=id)throw std::runtime_error("Missing destructable doodad state");out.u32(d.type);out.u32(d.position.x.bits());out.u32(d.position.y.bits());for(float value:{d.z,d.deformationBase,d.angle,d.life,d.maxLife,d.occluder,d.animationRate})f32(out,value);for(float value:d.scale)f32(out,value);out.u32(std::bit_cast<std::uint32_t>(d.variation));out.u32(std::bit_cast<std::uint32_t>(d.editorId));for(bool value:{d.visible,d.solid,d.invulnerable,d.initialDead})out.u32(value?1:0);out.u64(d.lifeRevision);for(double value:{d.animationStart,d.animationPhase,d.animationRateStart})f64(out,value);out.text(d.animation,1024);if(d.animationQueue.size()>256)throw std::runtime_error("Destructable animation queue exceeds budget");out.size(d.animationQueue.size());for(auto& value:d.animationQueue)out.text(value,1024);out.text(visual->animation,1024);out.text(visual->randomAnimation,1024);f64(out,visual->animationStart);f64(out,visual->randomStart);out.u32(visual->randomPhase);}
    return sealSnapshot(out.finish(),budget);
}
